  "sinHabilidad": false,
  "texto": "Furia. Si controlas Dragones reduce su coste en un Oro. Una vez por turno, genera un oro para aliados y destruye hasta una carta una carta de coste 2 o menos. Al comienzo del turno, si esta en juego o en tu cementerio, un oro o carta de coste 2 o menos pierde su habilidad por el turno"
