  "texto": "Busca en tu Castillo tres Oros. Pon dos de ellos en tu Oro Pagado, sin habilidad por el turno, y el otro en tu mano. Si controlas siete o más Oros, roba dos cartas. Cuando pongas un Oro en juego, puedes subir este Talismán de tu Cementerio a tu mano."
