  "texto": "Prevén que un Aliado sea Anulado, Destruido, Desterrado o cambie de controlador. En tu Vigilia, si no has puesto Oros en juego este turno, puedes convertir este Talismán de tu mano en un Oro sin habilidad, ponlo en tu Reserva y Roba una carta."
