  "nombre": "La Estrella Solitaria",
  "tipo": "Oro",
  "coste": 0,
  "fuerza": 0,
  "razas": [
   "No aplica"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Una vez por turno, puedes pagar un Oro para buscar en tu Castillo una carta que no sea Talismán y ponla en tu mano. Tus demás Oros no pueden ser afectados por Talismanes oponentes y tus Aliados no pueden perder su habilidad."
