  "texto": "Exhumar. El portador gana 3 de Fuerza y Furia. Cuando entra en juego, genera un Oro por el turno. Al comienzo de cada turno, tu oponente Baraja una carta de su mano. Si controlas otra Arma, Roba dos cartas."
