  "sinHabilidad": false,
  "texto": "En tu Vigilia, una vez por turno puedes pagar el coste de una carta oponente para que pierda su habilidad y sea Destruida. Juega esa carta bajo tu control sin pagar su coste. Las cartas oponentes no disparan sus habilidades al salir del juego."
