  "texto": "Cuando entra en juego, juega un Tótem de coste 3 de tu Castillo sin pagar su coste. Los Aliados en juego pierden su habilidad. En tu Vigilia, una vez por turno, tu oponente Destierra una carta de la parte superior de su Castillo por cada Tótem que controles."
