  "razas": [],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "En tu Vigilia, una vez por turno, puedes buscar en tu Castillo un Aliado y un Oro y ponerlos en tu mano. En tu Vigilia, una vez por turno, un Aliado que controles gana Furia por el turno y su daño es enviado al Destierro este turno."
