  "sinHabilidad": false,
  "texto": "Una vez en tu turno, muestra cartas del tope de tu Castillo hasta mostrar un Aliado de coste 2 o menos y ponlo en tu mano. Para jugar un Aliado de coste 2 o menos, debe lanzarse un dado de seis caras. Si sale impar, no dispara sus habilidades al entrar en juego."
