  "texto": "Cuando entra en juego, busca un Tótem Monte en tu Castillo y ponlo en tu mano. Una vez por turno, puedes Descartar una carta para jugar un Aliado de coste 3 o más de tu Cementerio reduciendo su coste en un Oro. Tus Aliados ganan 1 de Fuerza e Indestructible."
