  "nombre": "Ramón Freire",
  "tipo": "Aliado",
  "coste": 1,
  "fuerza": 2,
  "razas": [
   "Caballero"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Cuando entra en juego, Roba dos cartas. Si controlas Aliados de coste 2 o más, puedes Desterrarlo de tu mano o en juego para generar un Oro para jugar Armas. Sólo puedes utilizar la habilidad de Ramón Freire una vez por turno."
