  "fuerza": 4,
  "razas": [
   "Héroe"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Puedes jugar tus Aliados al comienzo del Bloqueo y no pueden ser Anulados. Cuando entra en juego, busca en tu Castillo un Aliado y ponlo en tu mano. Tus Aliados Héroe no pueden salir del juego en Batalla Mitológica."
