  "fuerza": 2,
  "razas": [
   "Héroe"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Indestructible. Cuando entra en juego, busca en tu Castillo un Aliado y ponlo en tu mano. Si buscaste un Carrera, genera un Oro por el turno para jugar Aliados de coste 2 o más."
