  "nombre": "Javiera Carrera",
  "tipo": "Aliado",
  "coste": 2,
  "fuerza": 2,
  "razas": [
   "Héroe"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Una vez por turno, un Aliado duplica su Fuerza por el turno. Si es un Carrera, en vez de eso triplica su Fuerza y no puede salir del juego hasta tu próximo turno. Una vez en tu Vigilia, Destierra hasta tres cartas de un Cementerio y Roba una carta."
