  "coste": 1,
  "fuerza": 3,
  "razas": [
   "Héroe"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "No puede ser Anulado. Cuando entra en juego, muestras cartas de tu Castillo hasta mostrar un Oro, ponlo en tu mano y Baraja el resto. En tu turno, cancelar la habilidad de tus Aliados Héroes cuesta un Oro adicional."
