  "nombre": "Jose Miguel Carrera",
  "tipo": "Aliado",
  "coste": 2,
  "fuerza": 4,
  "razas": [
   "Héroe"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Furia. Cuando ataques con un sólo Aliado, nombra un coste. Hasta tu próximo turno a tu oponente le cuesta un Oro adicional utilizar habilidades de Aliados de ese coste. Cuanto este u otro Aliado que controles salga del juego, una vez por turno, Roba una carta."
