  "coste": 1,
  "fuerza": 1,
  "razas": [
   "Héroe"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Indestructible. No puede ser Anulado y puedes jugarlo al comienzo del Bloqueo. Cuando entra en juego o ataques con un sólo Aliado, un Aliado gana 3 de Fuerza por el turno y su daño es enviado al Destierro."
