  "fuerza": 2,
  "razas": [
   "Héroe"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Indestructible. En tu Vigilia, una vez por turno, puedes hacer que un Aliado gane 1 de Fuerza, Furia y haga doble daño de combate este turno."
