  "nombre": "Manuel Rodriguez",
  "tipo": "Aliado",
  "coste": 2,
  "fuerza": 4,
  "razas": [
   "Héroe"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Furia. Hace doble daño de combate al Destierro. Cuando ataque solo, Roba una carta y hasta tu próximo turno a tu oponente le cuesta un Oro adicional afectar a tus Aliados. Al comienzo del turno, genera un Oro para Aliados o Baraja una carta de coste 3 o menos."
