  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Furia. Puedes Descartar o Destruir una carta que controles para reducir su coste en dos Oros. Cuando entra en juego, busca en tu Castillo un Aliado Alfa y ponlo en tu mano. Cuando ataques, tu oponente Bota tres cartas."
