  "sinHabilidad": false,
  "texto": "Puedes Botar tres cartas para jugarlo desde tu Cementerio pagando su coste. En tu Vigilia, una vez por turno, busca una carta en tu Castillo, ponla en tu Cementerio y un Aliado gana Furia por el turno. Tus demás Aliados ganan 1 de Fuerza."
