  "fuerza": 3,
  "razas": [
   "Bestia"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "En tu Vigilia, una vez por turno, puedes buscar un Aliado en tu Castillo y ponerlo en tu Cementerio. Un Aliado en juego gana tanta Fuerza como coste tenga el Aliado buscado. Cuando sea Destruido, tu oponente Bota cartas igual a la Fuerza de un Aliado en juego."
