  "texto": "Furia. Una vez por turno, puedes buscar un Aliado Bestia en tu Castillo y ponerlo en tu Cementerio para que un Aliado gane o pierda 2 de Fuerzapor el turno. Puedes Desterrarlo de tu Cementerio para que una carta pierda su habilidad por el turno."
