  "nombre": "Ignis Azotamundos",
  "tipo": "Aliado",
  "coste": 2,
  "fuerza": 4,
  "razas": [
   "Sombra"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Una vez en tu turno, Destruye una carta que controles para Desterrar hasta dos cartas de coste 2 o menos y Robar una carta. Puedes Desterrarlo de tu Cementerio para poner en juego otro Aliado de tu Cementerio como un Aliado sin habilidad de nombre Titán."
