  "nombre": "Jack",
  "tipo": "Aliado",
  "coste": 1,
  "fuerza": 2,
  "razas": [
   "Sombra"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Cuando entra en juego, si tu oponente tiene tres o más cartas en su Destierro, convierte un Aliado oponente de coste 2 o menos en un Aliado Sombra sin habilidad de Fuerza 1 y gana su control. Los Aliados atacantes pierden 1 de Fuerza."
