  "nombre": "James Moriarty",
  "tipo": "Aliado",
  "coste": 1,
  "fuerza": 2,
  "razas": [
   "Sombra"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Exhumar. Cuando entra en juego, Roba una carta. Una vez por turno, si tu oponente tiene ocho o más cartas en su Destierro, puedes Destruir otro Aliado que controles para prevenir el próximo daño que fueras a recibir."
