  "nombre": "La Fiura",
  "tipo": "Aliado",
  "coste": 1,
  "fuerza": 3,
  "razas": [
   "Sombra"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Exhumar Una vez en tu turno, puedes Barajar una carta de tu mano para buscar una carta del mismo tipo en un Castillo y ponerla en el Destierro o Cementerio de su dueño. Si buscaste a El Trauco, Roba una carta."
