  "razas": [
   "Sombra"
  ],
  "oroInicial": false,
  "sinHabilidad": false,
  "texto": "Cuando entra en juego, si tu oponente tiene ocho o más cartas en su Destierro, convierte dos Oros oponentes en Oros sin habilidad. Esta habilidad no puede ser cancelada Una vez en tu turno, tu oponente Destierra una carta carta del tope de su Castillo."
