  "texto": "Puedes tener más de tres copias en tu Castillo. Cuando entra en juego, puedes buscar un Aliado en tu Castillo y ponlo en tu mano. Por cada Aliado de coste 2 que controles, los Aliados oponentes pierden 1 de Fuerza y tus Aliados ganan 1 de Fuerza."
