  "texto": "Indestructible. Cuando entra en juego, puedes barajar cartas en juego cuyos costes sumen hasta 5 y busca dos cartas en tu castillo y ponlas en tu mano. En tu fase final, baraja cuatro cartas de los cementerios y agrupa un aliado que controles"
