  "texto": "Reduce su coste en un Oro si muestras un Arma o Tótem de tu mano o Cementerio. Cuando entra en juego, mira la mano de tu oponente y Descarta una carta de ahí de coste 1. Los Aliados oponentes pierden 1 de Fuerza por cada Tótem que controles."
