  "sinHabilidad": false,
  "texto": "Cuando entra en juego, puedes agrupar hasta dos Oros que controles. Una vez por turno, puedes mostrar la primera carta de tu Castillo, si es un Oro o una carta de coste 2 o menos, puedes ponerla en tu mano."
